CREATE TABLE config_entries (id CHAR(36) PRIMARY KEY, environment VARCHAR(64) NOT NULL, tenant_id VARCHAR(191) NOT NULL DEFAULT '', service VARCHAR(191) NOT NULL, config_key VARCHAR(255) NOT NULL, config_value JSON NULL, secret_ref TEXT NOT NULL, status VARCHAR(32) NOT NULL, revision BIGINT NOT NULL, rollout_percentage INT NOT NULL DEFAULT 100, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, UNIQUE KEY config_entries_scope_uq(environment,tenant_id,service,config_key), INDEX config_entries_resolve_idx(environment,service,tenant_id,status,config_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE config_revisions (id VARCHAR(191) PRIMARY KEY, entry_id CHAR(36) NOT NULL, revision BIGINT NOT NULL, config_value JSON NULL, secret_ref TEXT NOT NULL, status VARCHAR(32) NOT NULL, rollout_percentage INT NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, UNIQUE KEY config_revisions_entry_uq(entry_id,revision), CONSTRAINT config_revisions_entry_fk FOREIGN KEY(entry_id) REFERENCES config_entries(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
